 2	///////////////////
 3	// Binary search
 4	///////////////////
 5	
 6	
 7	predicate isSorted(a:array<int>)
 8	  reads a
 9	{
10	  forall i:nat, j:nat :: i <= j < a.Length ==> a[i] <= a[j]
11	}
12	
13	
14	// a[lo] <= a[lo+1] <= ... <= a[hi-2] <= a[hi-1]  
15	method binSearch(a:array<int>, K:int) returns (b:bool)
16	  requires isSorted(a)
17	  ensures b == exists i:nat :: i < a.Length && a[i] == K
18	{
19		var lo: nat := 0 ;
20		var hi: nat := a.Length ;
21		while (lo < hi)
22	    decreases hi - lo
23	    invariant  0 <= lo <= hi <= a.Length
24	    //invariant forall j:nat :: j < lo ==> a[j] < K
25		{
26			var mid: nat := (lo + hi) / 2 ;   assert  lo <= mid <= hi ;
27			if (a[mid] < K) {                 assert  a[lo] <= a[mid]; 
28	                                      assert  a[mid] < K ;
29				lo := mid + 1 ;                 assert              mid < lo <= hi;
30			} else if (a[mid] > K) {          assert  K < a[mid];
31				hi := mid ;                     assert              lo <= hi == mid;
32			} else {
33				return true ;                   assert a[mid] == K;
34			}
35		}
36		return false ;                     
37	}
38	
39	/* Note: the following definition of isSorted:
40	
41	predicate isSorted(a:array<int>)
42	  reads a
43	{
44	  forall i:nat :: i < a.Length - 1 ==> a[i] <= a[i+1]
45	}
46	
47	although equivalent to the one above is not enough for Dafny to be able 
48	to prove the invariants for the loop in binSearch.
49	
50	The given one works because it *explicitly* states that every element 
51	of the input array is smaller than or equal to all later elements. 
52	This fact is implied by the alternative definition of isSorted given 
53	here (which only talks about array elements and their successors). 
54	However, it needs to be derived as an auxiliary lemma first, something 
55	that Dafny is not currently able to do automatically. 
56	*/
57	
